SELECT gen_random_uuid()::text, 'formula', '$S \ge \frac{P_{demand}}{\text{pf}}$', 'Transformer kVA for a Demand Load', '$S_{xfmr} \ge \frac{P_{demand}}{\text{pf}}\ (\text{next standard size}),\qquad I_{svc} = \frac{S}{\sqrt3V_L}$', '$\text{kVA}$', 'Sizing the service transformer and the service current from the building''s demand load.', '[{"symbol":"$P_{demand}$","meaning":"demand load after demand factors","unit":"$\\text{kW}$"},{"symbol":"$\\text{pf}$","meaning":"power factor","unit":null},{"symbol":"$V_L$","meaning":"service line voltage","unit":"$\\text{V}$"}]'::jsonb, 'Standard ratings: 15, 25, 37.5, 50, 75, 100, 167 kVA (single phase); 75–2500 kVA (three phase).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'feeders and services' AND s."active"), NULL, false, 'PENDING', now(), now()
