SELECT gen_random_uuid()::text, 'formula', '$\text{CM} = \frac{kKIL}{\text{VD}}$', 'Conductor Size for a Voltage-Drop Limit', '$\text{CM} = \frac{kKIL}{\text{VD}},\quad k = 2\ (1\phi),\ \sqrt3\ (3\phi);\quad K \approx 10.4\ (\text{Cu}),\ 17\ (\text{Al})\ \Omega\cdot\text{cmil/ft}$', '$\text{cmil}$', 'The minimum conductor area (circular mils) to keep the drop within a limit; then pick the size with at least that area AND enough ampacity.', '[{"symbol":"$K$","meaning":"resistivity of the conductor","unit":"$\\Omega\\cdot\\text{cmil/ft}$"},{"symbol":"$I$","meaning":"load current","unit":"$\\text{A}$"},{"symbol":"$L$","meaning":"one-way length","unit":"$\\text{ft}$"},{"symbol":"$\\text{VD}$","meaning":"allowed voltage drop","unit":"$\\text{V}$"}]'::jsonb, 'Use one-way length: k already counts the return conductor.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'conductor and conduit sizing' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
