SELECT gen_random_uuid()::text, 'formula', '$I_{IR} \ge I_{sc}$', 'Interrupting Rating Check', '$I_{interrupting} \ge I_{sc}\ \text{at the line terminals},\qquad I_{rating} \ge I_{load}\ (\le \text{ampacity})$', '$\text{kA}$', 'An overcurrent device must interrupt the largest fault it can see, not just carry the load.', '[{"symbol":"$I_{interrupting}$","meaning":"device interrupting rating (AIC)","unit":"$\\text{kA}$"},{"symbol":"$I_{sc}$","meaning":"available fault current where it is installed","unit":"$\\text{kA}$"}]'::jsonb, 'Main breakers near a large transformer often need 42–65 kA; branch breakers may be 10 kA only if the fault level there is lower.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'overcurrent protection' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE'
