SELECT gen_random_uuid()::text, 'formula', '$I_{LR} = \frac{k\cdot\text{hp}\cdot1000}{\sqrt3V}$', 'Locked-Rotor Current from Code Letter', '$I_{LR} = \frac{(\text{kVA/hp}) \times \text{hp} \times 1000}{\sqrt3\,V}\quad (\text{e.g. code G: } 5.6\text{–}6.29\ \text{kVA/hp})$', '$\text{A}$', 'The starting (locked-rotor) current from the motor''s nameplate code letter.', '[{"symbol":"$\\text{kVA/hp}$","meaning":"locked-rotor kVA per hp for the nameplate code letter","unit":null},{"symbol":"$\\text{hp}$","meaning":"motor rating","unit":null},{"symbol":"$V$","meaning":"line voltage","unit":"$\\text{V}$"}]'::jsonb, 'Use the upper end of the letter''s range for a worst case.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'motor circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
