SELECT gen_random_uuid()::text, 'formula', '$I_{disc} \ge 1.15I_{FLC}$', 'Motor Disconnect Rating', '$I_{disconnect} \ge 1.15\,I_{FLC}\quad (\text{or horsepower-rated at least the motor\''s hp})$', '$\text{A}$', 'A motor''s disconnecting means must be rated at least 115% of its full-load current.', '[{"symbol":"$I_{FLC}$","meaning":"motor full-load current from the code tables","unit":"$\\text{A}$"}]'::jsonb, 'Use the TABLE full-load current, not the nameplate, for sizing.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'motor circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
