SELECT gen_random_uuid()::text, 'formula', '$V_{ret} = \frac{S_{sc}}{S_{sc} + S_{LR}}$', 'Motor Starting Voltage Dip', '$V_{retained} = \frac{S_{sc}}{S_{sc} + S_{LR}},\qquad \text{dip} = \frac{S_{LR}}{S_{sc} + S_{LR}}$', NULL, 'How far the bus voltage sags when a motor starts across the line.', '[{"symbol":"$S_{sc}$","meaning":"short-circuit kVA of the source at the motor bus","unit":"$\\text{kVA}$"},{"symbol":"$S_{LR}$","meaning":"motor locked-rotor kVA","unit":"$\\text{kVA}$"}]'::jsonb, 'More than about 15–20% dip flickers lights and can drop out contactors: consider reduced-voltage starting.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'motor circuits' AND s."active"), NULL, true, 'PENDING', now(), now()
