SELECT gen_random_uuid()::text, 'formula', '$\text{VD} = kr\sum I_jL_j$', 'Feeder Voltage Drop with Tapped Loads', '$\text{VD} = k\,r\sum_j I_jL_j\quad (\text{each load times its distance from the source})$', '$\text{V}$', 'Drop to the far end of a feeder with several loads along it: the sum of current-distance moments.', '[{"symbol":"$I_j$","meaning":"current of load j","unit":"$\\text{A}$"},{"symbol":"$L_j$","meaning":"distance of load j from the source","unit":"$\\text{m}$"},{"symbol":"$r$","meaning":"resistance per unit length of one conductor","unit":"$\\Omega/\\text{m}$"},{"symbol":"$k$","meaning":"2 single phase, √3 three phase","unit":null}]'::jsonb, 'Same as adding each segment''s current times its length; only valid at unity pf or with impedance in place of r.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'voltage drop' AND s."active"), NULL, false, 'PENDING', now(), now()
