SELECT gen_random_uuid()::text, 'formula', '$I_2 = \frac{I_1}{1 + f},\ f = \frac{\sqrt3LI_1}{CnE}$', 'Point-to-Point Fault Current', '$f = \frac{\sqrt3\,L\,I_{sc,1}}{C\,n\,E_{LL}}\ (3\phi),\quad \frac{2LI_{sc,1}}{CnE_{LL}}\ (1\phi);\qquad I_{sc,2} = \frac{I_{sc,1}}{1 + f}$', '$\text{A}$', 'Fault current at the end of a cable run from the fault current at its start.', '[{"symbol":"$L$","meaning":"conductor length","unit":"$\\text{ft}$"},{"symbol":"$I_{sc,1}$","meaning":"fault current at the start of the run","unit":"$\\text{A}$"},{"symbol":"$C$","meaning":"conductor constant (from tables)","unit":null},{"symbol":"$n$","meaning":"conductors in parallel per phase","unit":null},{"symbol":"$E_{LL}$","meaning":"line voltage","unit":"$\\text{V}$"}]'::jsonb, 'f is the cable impedance over the source impedance; the multiplier 1/(1 + f) is always below 1.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'short-circuit calculation' AND s."active"), NULL, false, 'PENDING', now(), now()
