SELECT gen_random_uuid()::text, 'formula', '$I_{mc} \approx 4\sum I_{FLC}$', 'Motor Contribution to Fault Current', '$I_{motor\ contribution} \approx 4 \times \sum I_{FLC}\ (\text{running motors, first cycles})$', '$\text{A}$', 'Running motors feed a fault for the first few cycles, adding to the utility''s contribution.', '[{"symbol":"$I_{FLC}$","meaning":"full-load currents of the running motors","unit":"$\\text{A}$"}]'::jsonb, 'Add it at the bus where the motors connect when checking interrupting ratings.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'short-circuit calculation' AND s."active"), NULL, false, 'PENDING', now(), now()
