SELECT gen_random_uuid()::text, 'formula', '$\frac{1}{\text{MVA}_s} = \sum\frac{1}{\text{MVA}_i}$', 'MVA Method', '$\text{series: } \frac{1}{\text{MVA}_{tot}} = \sum\frac{1}{\text{MVA}_i};\quad \text{parallel: } \text{MVA}_{tot} = \sum\text{MVA}_i;\quad \text{MVA}_i = \frac{\text{MVA}_{rated}}{Z_{pu}}$', '$\text{MVA}$', 'Fault level by combining each element''s short-circuit MVA like conductances: no common base needed.', '[{"symbol":"$\\text{MVA}_i$","meaning":"short-circuit MVA of each element on its own","unit":null},{"symbol":"$Z_{pu}$","meaning":"its per-unit impedance on its own rating","unit":null}]'::jsonb, 'Series elements combine like resistors in parallel, parallel sources simply add.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'short-circuit calculation' AND s."active"), NULL, false, 'PENDING', now(), now()
