SELECT gen_random_uuid()::text, 'formula', '$R > 25\ \Omega \implies \text{add an electrode}$', 'Supplementary Electrode Rule', '$R_{rod} > 25\ \Omega \implies \text{add a supplemental electrode} \ge 1.8\ \text{m away}$', NULL, 'A single made electrode above 25 Ω must be supplemented by a second one.', '[{"symbol":"$R_{rod}$","meaning":"resistance of a single rod, pipe or plate electrode to earth","unit":"$\\Omega$"}]'::jsonb, 'Two rods closer than their length interfere; space them at least 1.8 m, ideally twice the rod length.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'grounding' AND s."active"), NULL, true, 'PENDING', now(), now()
