SELECT gen_random_uuid()::text, 'formula', '$R_n \approx \frac{R_1}{n}F$', 'Rods in Parallel', '$R_n \approx \frac{R_1}{n}F,\qquad F \approx 1.2\text{–}1.5\ (\text{spacing} \approx \text{rod length})$', '$\Omega$', 'Several rods lower the resistance, but less than 1/n because their fields overlap.', '[{"symbol":"$R_1$","meaning":"resistance of one rod","unit":"$\\Omega$"},{"symbol":"$n$","meaning":"number of rods","unit":null},{"symbol":"$F$","meaning":"mutual-interference factor","unit":null}]'::jsonb, 'Wider spacing brings F toward 1.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
