SELECT gen_random_uuid()::text, 'formula', '$\text{unbalance} = \frac{\max - \text{avg}}{\text{avg}}$', 'Panel Phase Balance', '$\text{unbalance} = \frac{I_{\max} - I_{avg}}{I_{avg}} \times 100\%\quad (\text{phase loads on a panel schedule})$', NULL, 'How evenly a panel''s circuits are spread over the phases.', '[{"symbol":"$I_{\\max}$","meaning":"most heavily loaded phase","unit":"$\\text{A}$"},{"symbol":"$I_{avg}$","meaning":"average of the three phases","unit":"$\\text{A}$"}]'::jsonb, 'Balance within about 10% so the neutral current and feeder size stay small.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'plans and specifications' AND s."active"), NULL, true, 'PENDING', now(), now()
