SELECT gen_random_uuid()::text, 'formula', '$\text{LLF} = \text{LLD}\cdot\text{LDD}\cdot\ldots$', 'Light Loss Factor', '$\text{LLF} = \text{LLD} \times \text{LDD} \times \text{RSDD} \times \text{BF} \times \ldots$', NULL, 'Everything that reduces light over time, multiplied: the maintenance factor of the lumen method.', '[{"symbol":"$\\text{LLD}$","meaning":"lamp lumen depreciation","unit":null},{"symbol":"$\\text{LDD}$","meaning":"luminaire dirt depreciation","unit":null},{"symbol":"$\\text{RSDD}, \\text{BF}$","meaning":"room surface dirt, ballast factor","unit":null}]'::jsonb, 'Design for maintained illuminance: initial lux is higher by 1/LLF.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'lumen method' AND s."active"), NULL, true, 'PENDING', now(), now()
