SELECT gen_random_uuid()::text, 'formula', '$E_h = \frac{I\cos^3\theta}{h^2}$', 'Horizontal and Vertical Illuminance', '$E_h = \frac{I\cos^3\theta}{h^2},\qquad E_v = \frac{I\sin\theta\cos^2\theta}{h^2}$', '$\text{lx}$', 'Illuminance at a point from its mounting height instead of the slant distance.', '[{"symbol":"$I$","meaning":"intensity toward the point","unit":"$\\text{cd}$"},{"symbol":"$h$","meaning":"mounting height above the point","unit":"$\\text{m}$"},{"symbol":"$\\theta$","meaning":"angle from the vertical","unit":null}]'::jsonb, 'Same as I cosθ/d² with d = h/cosθ. Several sources: add their contributions.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'point-by-point method' AND s."active"), NULL, false, 'PENDING', now(), now()
