SELECT gen_random_uuid()::text, 'formula', '$t \ge 90\ \text{min},\ E_{avg} \ge 10\ \text{lx}$', 'Emergency Lighting Duration and Level', '$t \ge 1.5\ \text{h};\quad E_{avg} \ge 10.8\ \text{lx}\ (1\ \text{fc}),\ E_{\min} \ge 1.1\ \text{lx}\ (0.1\ \text{fc}) \text{ along egress};\quad C = \frac{P\,t}{V\cdot\text{DoD}}$', '$\text{Ah}$', 'Emergency lighting must light the exit path for 90 minutes; the battery is sized for that.', '[{"symbol":"$P$","meaning":"emergency lighting load","unit":"$\\text{W}$"},{"symbol":"$V$","meaning":"battery voltage","unit":"$\\text{V}$"},{"symbol":"$\\text{DoD}$","meaning":"usable depth of discharge","unit":null}]'::jsonb, 'Values follow NFPA 101, adopted by the Philippine Fire Code; check the local requirement.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'emergency and energy-efficient lighting' AND s."active"), NULL, false, 'PENDING', now(), now()
