SELECT gen_random_uuid()::text, 'formula', '$\text{payback} = \frac{C_{retrofit}}{\Delta P\,t\,r}$', 'Lighting Retrofit Payback', '$\text{payback} = \frac{C_{retrofit}}{\Delta P\,t\,r/1000}\ \text{years}$', '$\text{yr}$', 'How many years of energy savings pay for a lighting upgrade.', '[{"symbol":"$C_{retrofit}$","meaning":"cost of the upgrade","unit":"$\\text{₱}$"},{"symbol":"$\\Delta P$","meaning":"watts saved","unit":"$\\text{W}$"},{"symbol":"$t$","meaning":"operating hours per year","unit":"$\\text{h}$"},{"symbol":"$r$","meaning":"energy rate","unit":"$\\text{₱/kWh}$"}]'::jsonb, 'Long operating hours make retrofits pay fastest; add avoided lamp replacements for a fuller picture.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical System & Illumination Design' AND t."subject" = 'EE' AND s."normKey" = 'emergency and energy-efficient lighting' AND s."active"), NULL, false, 'PENDING', now(), now()
